css:
:root {
  --paper: #f4ecd8;
  --paper-edge: #e8dcbe;
  --ink: #23324a;
  --ink-soft: #5b6b85;
  --stamp-red: #a13d2b;
  --line: rgba(35, 50, 74, 0.22);
}

.sheet {
  position: relative;
  width: 380px;
  padding: 46px 52px;
  background: repeating-linear-gradient(
      0deg,
      rgba(35, 50, 74, 0.025) 0px,
      rgba(35, 50, 74, 0.025) 1px,
      transparent 1px,
      transparent 26px
    ),
    radial-gradient(
      ellipse at 15% 10%,
      rgba(255, 255, 255, 0.5),
      transparent 45%
    ),
    radial-gradient(
      ellipse at 85% 90%,
      rgba(120, 90, 50, 0.08),
      transparent 50%
    ),
    var(--paper);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.5) inset,
    0 2px 4px rgba(90, 70, 40, 0.15),
    0 25px 45px -25px rgba(35, 25, 10, 0.45);
  border-radius: 2px;
}

.sheet::before,
.sheet::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  height: 10px;
  background: var(--paper);
  background-image: linear-gradient(135deg, var(--paper) 50%, transparent 50%),
    linear-gradient(45deg, var(--paper) 50%, transparent 50%);
  background-size: 14px 14px;
  background-repeat: repeat-x;
}
.sheet::before {
  top: -9px;
}
.sheet::after {
  bottom: -9px;
  transform: scaleY(-1);
}

.sheet h1 {
  margin: 0 0 26px;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ink-soft);
  border-bottom: 1px dashed var(--line);
  padding-bottom: 14px;
}

.item {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 11px 0;
}

.stamp-checkbox {
  position: relative;
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  margin-top: 1px;
}

.stamp-checkbox input {
  position: absolute;
  inset: 0;
  opacity: 0;
  margin: 0;
  cursor: pointer;
  z-index: 2;
}

.stamp-checkbox .box {
  position: absolute;
  inset: 0;
  border: 2px solid var(--ink-soft);
  border-radius: 3px 5px 4px 6px;
  background: radial-gradient(
      ellipse at 30% 20%,
      rgba(255, 255, 255, 0.6),
      transparent 60%
    ),
    var(--paper-edge);
  box-shadow: inset 0 1px 2px rgba(35, 50, 74, 0.12);
  transition:
    border-color 0.25s ease,
    transform 0.15s ease,
    background 0.25s ease;
}

.stamp-checkbox input:active ~ .box {
  transform: scale(0.9);
}

.stamp-checkbox .mark {
  position: absolute;
  inset: -6px;
  pointer-events: none;
}

.stamp-checkbox .mark path {
  fill: none;
  stroke: var(--stamp-red);
  stroke-width: 5;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 40;
  stroke-dashoffset: 40;
  transition: stroke-dashoffset 0.35s ease 0.05s;
}

.stamp-checkbox .ring {
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 2px solid var(--stamp-red);
  opacity: 0;
  transform: scale(0.6);
}

.stamp-checkbox input:checked ~ .box {
  border-color: var(--stamp-red);
  background: #f9f1e2;
}

.stamp-checkbox input:checked ~ .mark path {
  stroke-dashoffset: 0;
}

.stamp-checkbox input:checked ~ .ring {
  animation: stampThump 0.5s ease forwards;
}

.stamp-checkbox input:focus-visible ~ .box {
  outline: 2px solid var(--ink);
  outline-offset: 3px;
}

@keyframes stampThump {
  0% {
    opacity: 0.9;
    transform: scale(1.4);
  }
  60% {
    opacity: 0.5;
    transform: scale(0.95);
  }
  100% {
    opacity: 0;
    transform: scale(1.1);
  }
}

.item label {
  color: var(--ink);
  font-size: 16px;
  line-height: 28px;
  cursor: pointer;
  user-select: none;
  transition: color 0.25s ease;
}

.stamp-checkbox input:checked ~ label {
  color: var(--ink-soft);
  text-decoration: line-through;
  text-decoration-color: var(--stamp-red);
  text-decoration-thickness: 1.5px;
}
